    lines = f.read().split('\n')

    if regime == 'words':
        tokenizer = word_splitter
    elif regime == 'chars':
        tokenizer = lambda line: char_splitter(line, '</s>')
    else:
        raise ValueError("unsupported regime {}".format(regime))

    if randomize:
        import random
        random.shuffle(lines)

    for line in lines:
