    """Creates a mask image from a given netCDF file"""
    import numpy as np
    import h5netcdf

    with h5netcdf.File(infile, "r") as topo:
        z = np.array(topo.variables[variable])
    if scale is not None:
        z = smooth_image(z, scale)
    data = get_mask_data(z)
    save_image(data, outfile)


