def parse_elevator_log_line(elevator_log_line, start_floor=0):
    current_floor = start_floor

    for char in elevator_log_line:
        if char == '[':
            current_floor += 1
        elif char == ']':
            current_floor -= 1
        else:
            sys.exit("Got an unsupported character {0}.".format(char))

    return current_floor


